#!/usr/bin/python
import os
import sqlite3
import sys

LOCK_TIMEOUT_SECONDS = 5.0


def fail(message, status=1):
    sys.stderr.write(message + "\n")
    return status


def main(argv):
    if len(argv) != 3:
        return fail("usage: reserve.py REQUEST_ID POSITIVE_QUANTITY", 2)

    request_id = argv[1]
    if not request_id:
        return fail("request ID must not be empty", 2)

    try:
        quantity = int(argv[2])
    except ValueError:
        return fail("quantity must be a positive integer", 2)
    if quantity <= 0:
        return fail("quantity must be a positive integer", 2)

    base = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
    path = os.path.join(base, "stock.db")
    db = None
    try:
        db = sqlite3.connect(path, timeout=LOCK_TIMEOUT_SECONDS)
        db.execute("PRAGMA busy_timeout = 5000")
        db.execute("BEGIN IMMEDIATE")

        prior = db.execute(
            "SELECT quantity FROM reservations WHERE request_id = ?",
            (request_id,),
        ).fetchone()
        if prior is not None:
            db.rollback()
            sys.stdout.write("reserved %s %d\n" % (request_id, prior[0]))
            return 0

        changed = db.execute(
            "UPDATE stock SET remaining = remaining - ? "
            "WHERE id = 1 AND remaining >= ?",
            (quantity, quantity),
        ).rowcount
        if changed != 1:
            db.rollback()
            return fail("insufficient stock")

        db.execute(
            "INSERT INTO reservations (request_id, quantity) VALUES (?, ?)",
            (request_id, quantity),
        )
        db.commit()
        sys.stdout.write("reserved %s %d\n" % (request_id, quantity))
        return 0
    except sqlite3.OperationalError as exc:
        if db is not None:
            db.rollback()
        if "locked" in str(exc).lower():
            return fail("database lock timeout")
        return fail("database error: %s" % exc)
    except sqlite3.DatabaseError as exc:
        if db is not None:
            db.rollback()
        return fail("database error: %s" % exc)
    finally:
        if db is not None:
            db.close()


if __name__ == "__main__":
    sys.exit(main(sys.argv))
